mapper.select:
select DISTINCT COLUMN_NAME
from information_schema.`COLUMNS`
where Table_Name = #{tableName,jdbcType=VARCHAR}

mapper.insert:
insert into CHB_PRDFEE_BASIS_DATA(POSUUID, PRODID, FPROD_ID, FEE_TYPE,CDATE, PAYDATE, TDY_POSITION, TDY_INTINCEXP_ADD, TDY_UNPAID_INTINCEXP, CCY, ORG_CODE, CREATE_TIME, UPDATE_TIME, DEPT_CODE, CREATE_USER, UPDATE_USER, DATA_SOURCE) select POSUUID, PRODID, FPROD_ID, FEE_TYPE,CDATE, PAYDATE, TDY_POSITION, TDY_INTINCEXP_ADD, TDY_UNPAID_INTINCEXP, CCY, ORG_CODE, CREATE_TIME, UPDATE_TIME, DEPT_CODE, CREATE_USER, UPDATE_USER, DATA_SOURCE from ( select TEMP.* from (
SELECT #{item.posuuid,jdbcType=VARCHAR} POSUUID, #{item.prodId,jdbcType=VARCHAR} PRODID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.feeType,jdbcType=VARCHAR} FEE_TYPE, #{item.cdate,jdbcType=DATE} CDATE, #{item.paydate,jdbcType=DATE} PAYDATE, #{item.tdyPosition,jdbcType=DECIMAL} TDY_POSITION, #{item.tdyIntincexpAdd,jdbcType=DECIMAL} TDY_INTINCEXP_ADD, #{item.tdyUnpaidIntincexp,jdbcType=DECIMAL} TDY_UNPAID_INTINCEXP, #{item.ccy,jdbcType=DECIMAL} CCY, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE FROM DUAL
) TEMP where not exists (select 1 from CHB_PRDFEE_BASIS_DATA CII where CII.PROD_ID = TEMP.PRODID AND CII.FPROD_ID = TEMP.FPROD_ID AND CII.FEE_TYPE = TEMP.FEE_TYPE) ) de ;
UPDATE CHB_PRDFEE_BASIS_DATA as A, ( select POSUUID, CDATE, PAYDATE, TDY_POSITION, TDY_INTINCEXP_ADD, TDY_UNPAID_INTINCEXP, CCY, ORG_CODE, CREATE_TIME, UPDATE_TIME, DEPT_CODE, CREATE_USER, UPDATE_USER, DATA_SOURCE from ( select TEMP.* from (
SELECT #{item.posuuid,jdbcType=VARCHAR} POSUUID, #{item.prodId,jdbcType=VARCHAR} PRODID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.feeType,jdbcType=VARCHAR} FEE_TYPE, #{item.cdate,jdbcType=DATE} CDATE, #{item.paydate,jdbcType=DATE} PAYDATE, #{item.tdyPosition,jdbcType=DECIMAL} TDY_POSITION, #{item.tdyIntincexpAdd,jdbcType=DECIMAL} TDY_INTINCEXP_ADD, #{item.tdyUnpaidIntincexp,jdbcType=DECIMAL} TDY_UNPAID_INTINCEXP, #{item.ccy,jdbcType=DECIMAL} CCY, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_PRDFEE_BASIS_DATA CII where CII.PROD_ID = TEMP.PRODID AND CII.FPROD_ID = TEMP.FPROD_ID AND CII.FEE_TYPE = TEMP.FEE_TYPE );
